<?php
if (!defined('GLPI_ROOT')) require_once dirname(__DIR__,3).'/inc/includes.php';
require_once dirname(__DIR__).'/bootstrap.php';
use GlpiPlugin\Projectplus\ConfigPage;
use GlpiPlugin\Projectplus\DocumentTemplate;
Session::checkRight('config', UPDATE);
$entity=(int)($_REQUEST['entities_id']??Session::getActiveEntity());
if($entity<0||!Session::haveAccessToEntity($entity)) Html::displayErrorAndDie(__('Entidade inválida.', 'projectplus'));
if(isset($_POST['save_template'])){ DocumentTemplate::save($entity,$_POST)?Session::addMessageAfterRedirect(__('Modelo salvo.', 'projectplus')):Session::addMessageAfterRedirect(__('Informe nome e documento PDF.', 'projectplus'),false,ERROR); Html::redirect($_SERVER['PHP_SELF'].'?entities_id='.$entity); }
if(isset($_POST['delete_template'])){ DocumentTemplate::delete((int)$_POST['id'],$entity); Html::redirect($_SERVER['PHP_SELF'].'?entities_id='.$entity); }
$edit=DocumentTemplate::get($entity,(int)($_GET['id']??0)); $edit=$edit[0]??['id'=>0,'document_type'=>'tap','name'=>'','version'=>'','documents_id'=>0,'is_active'=>1];
Html::header(__('Modelos de documentos', 'projectplus'),$_SERVER['PHP_SELF'],'config','plugins'); ConfigPage::begin('documents');
echo "<section class='projectplus-config-card'><header class='projectplus-config-card__header'><i class='ti ti-file-description'></i> ".ConfigPage::escape(__('Modelos TAP, TEP e TA','projectplus')).'</header><div class="projectplus-config-card__body">';
echo "<form method='get'><table class='tab_cadre_fixe'><tr><td>".__('Entidade','projectplus').'</td><td>'; Entity::dropdown(['name'=>'entities_id','value'=>$entity,'entity'=>$_SESSION['glpiactiveentities']??[$entity]]); echo " <button class='btn btn-secondary'>".__('Carregar').'</button></td></tr></table></form>';
echo "<form method='post'>".Html::hidden('_glpi_csrf_token',['value'=>Session::getNewCSRFToken()]).Html::hidden('entities_id',['value'=>$entity]).Html::hidden('id',['value'=>(int)$edit['id']])."<table class='tab_cadre_fixe'><tr class='tab_bg_2'><th colspan='2'>".((int)$edit['id']?__('Editar modelo','projectplus'):__('Novo modelo','projectplus')).'</th></tr>';
echo "<tr class='tab_bg_1'><td>".__('Tipo','projectplus').'</td><td>'; Dropdown::showFromArray('document_type',DocumentTemplate::types(),['value'=>$edit['document_type']]); echo '</td></tr>';
echo "<tr class='tab_bg_1'><td>".__('Nome','projectplus')."</td><td><input class='form-control' required name='name' value='".ConfigPage::escape((string)$edit['name'])."'></td></tr><tr class='tab_bg_1'><td>".__('Versão','projectplus')."</td><td><input class='form-control' name='version' value='".ConfigPage::escape((string)$edit['version'])."'></td></tr><tr class='tab_bg_1'><td>".__('PDF-base','projectplus').'</td><td>'; Dropdown::showFromArray('documents_id',DocumentTemplate::getDocumentsForEntity($entity),['value'=>(int)$edit['documents_id']]); echo '</td></tr>';
echo "<tr class='tab_bg_1'><td>".__('Ativo','projectplus').'</td><td>'; Dropdown::showYesNo('is_active',(int)$edit['is_active']); echo "</td></tr><tr class='tab_bg_1'><td colspan='2' class='center'><button class='btn btn-primary' name='save_template' value='1'>".__('Salvar').'</button></td></tr></table></form>';
echo "<table class='tab_cadre_fixe'><tr><th>".__('Tipo').'</th><th>'.__('Nome').'</th><th>'.__('Versão','projectplus').'</th><th>'.__('Ativo','projectplus').'</th><th>'.__('Ações','projectplus').'</th></tr>';
foreach(DocumentTemplate::get($entity) as $t){ echo "<tr class='tab_bg_1'><td>".ConfigPage::escape(DocumentTemplate::types()[$t['document_type']]).'</td><td>'.ConfigPage::escape($t['name']).'</td><td>'.ConfigPage::escape($t['version']).'</td><td>'.((int)$t['is_active']?__('Sim'):__('Não'))."</td><td><a class='btn btn-sm btn-secondary' href='?entities_id=$entity&id=".(int)$t['id']."'>".__('Editar')."</a> <form style='display:inline' method='post'>".Html::hidden('_glpi_csrf_token',['value'=>Session::getNewCSRFToken()]).Html::hidden('entities_id',['value'=>$entity]).Html::hidden('id',['value'=>(int)$t['id']])."<button class='btn btn-sm btn-danger' name='delete_template' value='1'>".__('Excluir').'</button></form></td></tr>'; }
echo '</table></div></section>'; ConfigPage::end(); Html::footer();
